// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any positive endowment of the contract.
        amount = bound(amount, 1, type(uint256).max / 2);

        // The deployer (this test contract) is the owner recorded by sGuardPlus,
        // so calling directly satisfies the __onlyOwner modifier for any amount.
        vm.deal(address(c), amount);

        c.sudicideAnyone();

        // General rule: after the owner self-destructs C, no code or funds remain
        // at its address. The mutant keeps the balance for every input.
        assertTrue(address(c).balance == 0, "selfdestruct must drain contract balance to owner");
    }
}
